-- mesh.lua
-- Generated by eilmer-mesher. Edit the .emesh.json project, not this file.
--   lmr prep-grids -j mesh.lua      registers the grids for a simulation
--   lmr custom-script -j mesh.lua   writes preview/blk-NNNN.vtk for the GUI
if config then config.dimensions = 2 end

-- points
p000 = Vector3:new{x=0.0, y=1.0}
p001 = Vector3:new{x=0.5, y=1.0}
p002 = Vector3:new{x=1.0, y=1.0}
p003 = Vector3:new{x=1.0, y=0.0}
p004 = Vector3:new{x=0.0, y=0.0}
p005 = Vector3:new{x=2.0, y=1.0}
p006 = Vector3:new{x=2.0, y=0.0}

-- paths
path_na1 = Line:new{p0=p000, p1=p001}
path_na2 = Line:new{p0=p001, p1=p002}
path_ref = Line:new{p0=p003, p1=p002}
path_sa = Line:new{p0=p004, p1=p003}
path_w = Line:new{p0=p004, p1=p000}
path_nb = Line:new{p0=p002, p1=p005}
path_e = Line:new{p0=p006, p1=p005}
path_sb = Line:new{p0=p006, p1=p003}

-- blocks
blocks = {}
-- block a
surf_a = CoonsPatch:new{north=Polyline:new{segments={path_na1, path_na2}}, east=path_ref, south=path_sa, west=path_w}
grid_a = StructuredGrid:new{psurface=surf_a, niv=11, njv=11, label="a"}
blocks[#blocks+1] = {grid=grid_a, tag="a", fsTag="initial", bcTags={west="inflow"}}

-- block b
surf_b = CoonsPatch:new{north=path_nb, east=path_e, south=ReversedPath:new{underlying_path=path_sb}, west=path_ref}
grid_b = StructuredGrid:new{psurface=surf_b, niv=11, njv=11, label="b"}
blocks[#blocks+1] = {grid=grid_b, tag="b", fsTag="initial", bcTags={east="outflow"}}

if registerFluidGrid then
   -- lmr prep-grids
   local ids = {}
   for i, b in ipairs(blocks) do
      ids[i] = registerFluidGrid{grid=b.grid, tag=b.tag, fsTag=b.fsTag, bcTags=b.bcTags}
   end
   -- Blocks are joined only across block split lines; a solid curve between
   -- two blocks stays a wall on both sides.
   connectGrids(ids[1], "east", ids[2], "west")
else
   -- lmr custom-script: preview output for the GUI
   os.execute("mkdir -p preview")
   for i, b in ipairs(blocks) do
      b.grid:write_to_vtk_file(string.format("preview/blk-%04d.vtk", i-1))
   end
end
